package handler

import (
	"encoding/base64"
	"net/http"
)

// encodedM3U contains the base64-encoded content of 1spotmedia_channels.m3u.
const encodedM3U = ""

var decodedM3U []byte

func init() {
	var err error
	decodedM3U, err = base64.StdEncoding.DecodeString(encodedM3U)
	if err != nil {
		panic("failed to decode embedded m3u: " + err.Error())
	}
}

// M3u serves the M3U playlist.
func M3u(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/vnd.apple.mpegurl; charset=utf-8")
	w.WriteHeader(http.StatusOK)
	w.Write(decodedM3U)
}
